// Event delegation survives every redraw and supports mouse, touch and keyboard.
document.addEventListener('click',event=>{const node=event.target.closest('[data-action]');if(node)perform(node.dataset.action,node.dataset.value);});
document.addEventListener('keydown',event=>{if(event.key==='Escape')hideTip();const node=event.target.closest('[data-action]');if(node&&['Enter',' '].includes(event.key)&&!['BUTTON','INPUT','SELECT'].includes(node.tagName)){event.preventDefault();perform(node.dataset.action,node.dataset.value);}});
for(const type of ['pointerover','focusin'])document.addEventListener(type,event=>{const node=event.target.closest('[data-tip],[data-driver]');if(node){if(node.dataset.tip!=null)showTip(tooltipItems[+node.dataset.tip],event,node);if(node.dataset.driver)emphasize(+node.dataset.driver);}});
document.addEventListener('pointerout',event=>{if(event.target.closest('[data-tip],[data-driver]'))hideTip();});document.addEventListener('focusout',hideTip);window.addEventListener('scroll',hideTip,{passive:true});window.addEventListener('resize',hideTip);
for(const [id,key] of [['round-min','min'],['round-max','max']])$(id).addEventListener('input',()=>{const v=Math.round(Number($(id).value)||1);update({[key]:key==='min'?Math.min(S.max,v):Math.max(S.min,v),definition:'analytical'});});

$('event-search').addEventListener('input',()=>{S.search=$('event-search').value;drawEvents();});$('close-dialog').addEventListener('click',()=>$('event-dialog').close());
$('reset').addEventListener('click',()=>{S.search='';$('event-search').value='';update({min:1,max:D.laps,drivers:[],noDrivers:false,definition:'analytical',type:'',compound:'',location:'',excluded:false,cycle:null,pair:null});history.replaceState(null,'',location.pathname);});
for(const [id,direction] of [['previous-range',-1],['next-range',1]])$(id).addEventListener('click',()=>{const width=S.max-S.min+1,min=Math.max(1,Math.min(D.laps-width+1,S.min+direction*width));update({min,max:min+width-1});});$('zoom-out').addEventListener('click',()=>{const span=Math.max(2,S.max-S.min+1);update({min:S.min-span,max:S.max+span});});
function csvSelection(){const fields=['event_id','lap','overtaker','overtaken','type','location_confidence'];return fields.join(',')+'\n'+currentEvents.map(e=>fields.map(k=>'"'+String(e[k]??'').replaceAll('"','""')+'"').join(',')).join('\n');}
function readHash(){try{const parsed=JSON.parse(decodeURIComponent(location.hash.slice(1)));for(const k of Object.keys(S))if(k in parsed)S[k]=parsed[k];S.location='';S.noDrivers=S.noDrivers===true;S.drivers=Array.isArray(S.drivers)?S.drivers.filter(n=>D.drivers.some(d=>d.driver_number===n)):[];if(!['analytical','on_track','lap1','all'].includes(S.definition))S.definition='analytical';S.min=Math.max(1,Math.min(D.laps,Number(S.min)||1));S.max=Math.max(S.min,Math.min(D.laps,Number(S.max)||D.laps));}catch{}}
// Drag brushing on plot backgrounds; sliders/inputs provide the keyboard alternative.
document.addEventListener('pointerdown',event=>{const svg=event.target.closest('svg[data-brush]');if(!svg||event.target.closest('[data-action]'))return;const rect=svg.getBoundingClientRect();brush={svg,rect,start:event.clientX,min:S.min,max:S.max};svg.setPointerCapture?.(event.pointerId);});
document.addEventListener('pointermove',event=>{if(!brush)return;const view=brush.svg.viewBox.baseVal,start=(brush.start-brush.rect.left)/brush.rect.width*view.width,end=(event.clientX-brush.rect.left)/brush.rect.width*view.width;let zone=brush.svg.querySelector('.brush-zone');if(!zone){zone=document.createElementNS('http://www.w3.org/2000/svg','rect');zone.setAttribute('class','brush-zone');brush.svg.appendChild(zone);}zone.setAttribute('x',Math.min(start,end));zone.setAttribute('y',25);zone.setAttribute('width',Math.abs(end-start));zone.setAttribute('height',view.height-75);});
document.addEventListener('pointerup',event=>{if(!brush)return;const b=brush;brush=null;if(Math.abs(event.clientX-b.start)<8)return;const width=b.svg.viewBox.baseVal.width,lap=x=>Math.round(b.min+Math.max(0,Math.min(1,((x-b.rect.left)/b.rect.width*width-60)/(width-85)))*(b.max-b.min));update({min:Math.min(lap(b.start),lap(event.clientX)),max:Math.max(lap(b.start),lap(event.clientX))});});
$('round-max').max=D.laps;$('round-min').max=D.laps;

const teams=[...new Set(D.drivers.map(d=>d.team))];$('team-picker').innerHTML=teams.map(team=>{const drivers=D.drivers.filter(d=>d.team===team);return `<button class="team-chip" data-action="team" data-value="${drivers.map(d=>d.driver_number).join(',')}" aria-pressed="false" style="--team-color:${color(drivers[0].driver_number)}">${esc(team)}</button>`;}).join('');
$('source-register').innerHTML='<p>Deze uitvoering is gedeeltelijk: locaties zijn zones en strategieverklaringen zijn niet volledig causaal vastgesteld. Brondefinities kunnen verschillen.</p><ul>'+D.warnings.map(w=>`<li>${esc(w)}</li>`).join('')+'</ul><p>Vaste brontellingen: '+esc(D.timing_source||'OpenF1')+' '+(D.stats.timing_original??D.stats.openf1_original)+' registraties; F1gures '+(D.f1gures_available?D.stats.f1gures_original+' netto passages':'onbekend; gebeurtenissen ontbreken')+'. Deze broncijfers veranderen niet mee met de filters.</p><ul>'+D.sources.map(s=>`<li><a href="${esc(s.url)}">${esc(s.title)}</a> · ${esc(s.publisher)} · ${esc(s.status)} · opgehaald ${esc(s.fetched_at)}</li>`).join('')+'</ul><a href="manifest.json">Volledig manifest</a>';
readHash();render();
